// Flappy Beans: the screensaver's "Earn my coffee" game, its name entry and
// the top 5. The physics live in lib/core (FlappyGame); this file only draws
// the sprites from flappy_img.c and forwards taps.

#include <cstdio>
#include <cstring>

#include "Ui.h"

// flappy_img.c, generated by tools/flappy_to_lvgl.py from assets/flappy/.
