LV_IMAGE_DECLARE(fb_button_play);
LV_IMAGE_DECLARE(fb_button_board);
LV_IMAGE_DECLARE(fb_button_text);  // blank, for text labels
LV_IMAGE_DECLARE(fb_button_text_wide);
LV_IMAGE_DECLARE(fb_button_ok);
LV_IMAGE_DECLARE(fb_button_pause);
LV_IMAGE_DECLARE(fb_button_resume);
LV_IMAGE_DECLARE(fb_new);
